window.CHAPTERS=window.CHAPTERS.concat([
{id:"2",title:"Principles of Management",focus:"How Taylor and Fayol turned experience into practical guidelines for managing work.",headline:"Principles guide judgement; they are flexible, not mechanical rules.",takeaways:["Management principles are broad guidelines derived from observation and experience; they help managers make informed decisions.","Taylor focused on shop-floor efficiency through scientific management; Fayol focused on general administrative principles.","Apply a principle to the case clue, then state the likely effect. Taylor and Fayol are complementary, not competing."],flow:[["Observe","Study the work"],["Standardise","Find the best method"],["Select","Match people to jobs"],["Cooperate","Train and support"],["Reward","Link pay to output"]],sections:[{title:"Nature and significance",lead:"Principles are general, flexible guidelines that explain relationships between managerial decisions and outcomes.",items:[["Universal but flexible","Useful across organisations, but applied in light of the situation."],["Mainly behavioural","They guide people and managerial relationships."],["Cause and effect","They help predict likely consequences of a managerial choice."],["Value","Improve resource use, decision quality, adaptation, social responsibility and management education."]]},{title:"Taylor: scientific management",lead:"Frederick Winslow Taylor sought higher productivity by replacing rule-of-thumb work with systematic study.",items:[["Science, not rule of thumb","Study each task and develop a best method."],["Harmony, not discord","Build cooperation between management and workers."],["Cooperation, not individualism","Share responsibility for applying scientific methods."],["Development of each person","Select and train workers for their abilities and potential."]]},{title:"Taylor's techniques",lead:"Use the exact technique named by the clue; several are easy to confuse.",items:[["Functional foremanship","Specialist foremen supervise different aspects of work."],["Standardisation and simplification","Set standards for tools, processes and quality; reduce unnecessary variety."],["Method, motion and time study","Find the best method; remove wasted movement; set a fair task time."],["Fatigue study","Set rest intervals to reduce tiredness and sustain output."],["Differential piece wage","Pay a higher rate to workers meeting the standard and a lower rate to those below it."]]},{title:"Fayol: 14 principles",lead:"Henri Fayol's principles apply across the organisation, especially its structure and administration.",items:[["Work and authority","Division of work; authority with responsibility; discipline."],["Direction and command","Unity of command; unity of direction; scalar chain."],["Organisation-wide interest","Subordination of individual interest; fair remuneration; centralisation in a suitable balance."],["Order and stability","Order; equity; stability of personnel."],["Initiative and team spirit","Initiative; esprit de corps; authority hierarchy with gang plank for urgent contact."]]},{title:"Two high-frequency distinctions",lead:"In case questions, identify the unit affected: one employee or a whole activity group.",items:[["Unity of command","One employee should receive orders from one superior."],["Unity of direction","One group of activities with the same objective should follow one head and one plan."],["Authority and responsibility","Right to give orders and obligation to perform should be balanced."],["Centralisation","Concentration of decision authority; Fayol favours a balance suited to circumstances."]]}],compare:{title:"Taylor and Fayol",heads:["Dimension","Taylor","Fayol"],rows:[["Focus","Shop-floor efficiency and work methods","Overall administration and organisation"],["Scope","Specialised, operational work","All levels and functions"],["Approach","Scientific study of tasks","General principles of management"],["Contribution","Techniques and scientific management principles","Fourteen administrative principles"]]},cues:[["One worker receives conflicting orders from two bosses","Unity of command"],["A manager uses one plan for all teams pursuing the same objective","Unity of direction"],["Work methods are tested to identify wasted movement","Motion study"],["Pay is higher only for workers who reach the set output standard","Differential piece wage"],["A specialist foreman gives instructions in a defined area","Functional foremanship"]],cards:[["Principles of management","Flexible general guidelines that help managers make decisions and understand likely effects."],["Science, not rule of thumb","Study a task systematically and develop the best method instead of relying on guesswork."],["Harmony, not discord","Management and workers should work in harmony rather than treat each other as opponents."],["Cooperation, not individualism","Managers and workers should cooperate in applying scientific methods."],["Development of each person","Select and train workers scientifically so each can reach their best ability."],["Functional foremanship","Taylor's technique in which specialist foremen supervise different functions."],["Motion study","Study movements in a task to remove unnecessary motions."],["Differential piece wage","Different wage rates reward workers who meet or exceed the standard."],["Unity of command","Each employee should receive orders from one superior."],["Unity of direction","One head and one plan should guide each group of activities with the same objective."]],mcqs:[{q:"A worker receives incompatible instructions from two supervisors. Which Fayol principle is violated?",o:["Unity of command","Unity of direction","Scalar chain","Order"],a:0,x:"Unity of command requires one employee to receive orders from one superior."},{q:"A company tests how long a standard job should take. Taylor's technique is:",o:["Time study","Motion study","Fatigue study","Method study"],a:0,x:"Time study determines a fair standard time for a task."},{q:"Removing unnecessary movements while doing a task is:",o:["Motion study","Time study","Fatigue study","Standardisation"],a:0,x:"Motion study analyses body and machine movements to eliminate waste."},{q:"Which principle says one head and one plan should guide activities with the same objective?",o:["Unity of direction","Unity of command","Scalar chain","Discipline"],a:0,x:"Unity of direction concerns a group of activities; unity of command concerns one employee."},{q:"Taylor's differential piece wage system links pay mainly to:",o:["Whether the worker reaches the output standard","Seniority in the organisation","The number of supervisors","Department size"],a:0,x:"Workers meeting the standard receive the higher rate."},{q:"A firm reduces unnecessary varieties of tools and product sizes. This is:",o:["Simplification","Fatigue study","Scalar chain","Initiative"],a:0,x:"Simplification reduces unnecessary variety; standardisation sets specifications."},{q:"Which best describes the scope of Fayol's principles?",o:["General administration across the organisation","Only production tasks on a shop floor","Only wage calculation","Only informal relationships"],a:0,x:"Fayol's principles address administration throughout the organisation."},{q:"Giving one team one plan for its shared sales objective applies:",o:["Unity of direction","Unity of command","Equity","Order"],a:0,x:"Unity of direction aligns a group of activities under one head and plan."},{q:"Which pair is correctly matched?",o:["Fatigue study — rest intervals","Time study — remove wasted movements","Motion study — set rest pauses","Method study — rank workers by ability"],a:0,x:"Fatigue study determines rest intervals to reduce fatigue."}],subjective:[{m:2,case:"A worker is told by both the production manager and quality manager to stop and restart the same job.",q:"Name the principle violated and state one likely consequence. (2 marks)",key:["Unity of command.","Confusion, conflict, weakened accountability or delay may result."]},{m:2,q:"State any two features of management principles. (2 marks)",key:["Any two explained: universal yet flexible; mainly behavioural; formed by practice and experimentation; cause-and-effect relationships; contingent application."]},{m:2,q:"Distinguish unity of command from unity of direction. (2 marks)",key:["Unity of command: one employee, one superior.","Unity of direction: one group of activities with one objective, one head and one plan."]},{m:2,case:"A factory tests alternative tool movements and removes motions that do not add value.",q:"Identify Taylor's technique and its purpose. (2 marks)",key:["Motion study.","It removes unnecessary movements to improve efficiency and reduce fatigue."]},{m:2,q:"State any two principles of scientific management given by Taylor. (2 marks)",key:["Any two: science not rule of thumb; harmony not discord; cooperation not individualism; development of each person."]},{m:2,case:"A firm has one output standard and pays a higher rate to workers who meet it.",q:"Identify the wage technique and its incentive. (2 marks)",key:["Differential piece wage system.","It rewards efficient workers with a higher rate and motivates output to the standard."]},{m:3,q:"Explain any three characteristics of management principles. (3 marks)",key:["They are general guidelines, not rigid rules.","They are flexible and contingent on the situation.","They mainly influence human behaviour or establish cause-and-effect relationships (one more)."]},{m:3,q:"Explain any three of Fayol's principles with a brief example. (3 marks)",key:["Name three accurate principles.","Explain each meaning correctly.","Give a relevant example or consequence for each."]},{m:3,case:"A company studies each job, trains workers in a tested method and sets a fair standard time.",q:"Identify and explain three Taylor techniques or principles shown. (3 marks)",key:["Method study: select the best way to perform the job.","Time study: establish a standard time for the task.","Scientific selection/training or science not rule of thumb: match workers to jobs and train them in the tested method."]},{m:3,q:"Explain three benefits of applying management principles. (3 marks)",key:["Provide useful managerial insights.","Support optimum use of resources and sound decisions.","Help adapt to change, meet social responsibility or support management education (one explained)."]},{m:3,case:"A manager allows urgent communication to bypass several ranks while preserving the normal reporting chain.",q:"Name the principle and explain when this arrangement is useful. (3 marks)",key:["Scalar chain with gang plank.","Scalar chain is the formal line of authority from highest to lowest.","A gang plank permits direct contact in an emergency to avoid harmful delay."]},{m:3,q:"Explain functional foremanship and one advantage and one limitation. (3 marks)",key:["Taylor's specialist foremen supervise different functional aspects of work.","Advantage: specialised expertise and closer supervision.","Limitation: a worker may receive instructions from several foremen, complicating unity of command."]},{m:4,q:"Explain four of Taylor's principles of scientific management. (4 marks)",key:["Science, not rule of thumb.","Harmony, not discord.","Cooperation, not individualism.","Development of each person to greatest efficiency and prosperity."]},{m:4,q:"Explain four Fayol principles that help establish sound authority and teamwork. (4 marks)",key:["Any four correctly explained: authority and responsibility; discipline; unity of command; unity of direction; scalar chain; equity; esprit de corps; subordination of individual interest."]},{m:4,case:"Two product divisions share a marketing team, receive instructions from multiple managers and compete for the same sales target.",q:"Identify two Fayol principles at risk and recommend changes. (4 marks)",key:["Unity of direction is at risk if activities with one objective lack one head and plan.","Unity of command is at risk if individual employees receive conflicting orders.","Assign a clear plan and accountable head to each objective or division.","Clarify reporting authority and coordinate shared resources."]},{m:4,q:"Compare Taylor and Fayol on focus, scope and contribution. (4 marks)",key:["Taylor focused on shop-floor productivity; Fayol on overall administration.","Taylor's approach was specialised and operational; Fayol's applied across levels and functions.","Taylor contributed scientific principles and work-study techniques.","Fayol contributed fourteen general administrative principles."]},{m:4,case:"A plant changes tool sizes, studies rest needs and uses two rates depending on whether workers meet the standard.",q:"Identify three scientific management techniques and explain their purpose. (4 marks)",key:["Standardisation/simplification: set specifications and remove needless variety.","Fatigue study: decide suitable rest intervals.","Differential piece wage: reward workers reaching the standard.","Explain how the combined method aims to raise productivity and efficiency."]},{m:4,q:"Explain why management principles are not rigid laws and how managers should use them. (4 marks)",key:["Human behaviour and business conditions vary.","Principles are broad guidelines, not fixed commands.","Their application depends on the situation and organisational values.","Managers use them to guide judgement, predict effects and adapt decisions."]}],
},
{id:"3",title:"Business Environment",focus:"How external forces shape business decisions, opportunities and risks.",headline:"Read the outside change, then connect it to a business consequence.",takeaways:["Business environment is the total of external forces that influence a business; managers cannot control most of them directly.","Its features include totality, interrelatedness, dynamism, uncertainty, complexity and relativity.","The dimensions are economic, social, technological, political and legal. Identify the source of change before explaining its effect."],flow:[["Notice","Scan external changes"],["Classify","Name the dimension"],["Interpret","Find opportunity or threat"],["Respond","Adapt policy or plans"],["Review","Monitor the new context"]],sections:[{title:"Meaning and features",lead:"Business environment is the sum total of external individuals, institutions and forces that affect business performance.",items:[["Totality","Many external forces together create the environment."],["Specific and general forces","Customers, suppliers and competitors affect a firm directly; broader forces shape the whole industry."],["Interrelated","A change in one force can affect other forces."],["Dynamic and uncertain","Forces keep changing and their timing or effect may be hard to predict."],["Complex and relative","Many factors interact; the same change can affect firms or regions differently."]]},{title:"Why it matters",lead:"Environmental awareness improves decisions before a change becomes a crisis.",items:[["Identify opportunities and first-mover advantage","Spot unmet needs or new technology early."],["Identify threats","Prepare for regulation, substitutes, shortages or shifts in demand."],["Access useful resources","Understand suppliers, talent, capital and technology."],["Adapt and plan","Align policies with changing conditions."],["Improve performance and image","Responsive, lawful and responsible firms earn trust."]]},{title:"Five dimensions",lead:"A quick mnemonic: E-S-T-P-L — economic, social, technological, political, legal.",items:[["Economic","Income, inflation, interest rates, taxation, economic growth, exchange rates and capital markets."],["Social","Customs, values, education, lifestyle, demographics, family patterns and consumer preferences."],["Technological","Innovation, automation, production methods, digital systems and research."],["Political","Government stability, priorities, ideology and attitude toward business."],["Legal","Acts, rules, court decisions and administrative orders that govern business."]]},{title:"Liberalisation, privatisation, globalisation",lead:"The 1991 reform package changed the Indian business environment and intensified competition.",items:[["Liberalisation","Removal or reduction of unnecessary government controls and restrictions."],["Privatisation","Greater role for the private sector and reduced government ownership or management in selected areas."],["Globalisation","Integration of the domestic economy with the world economy through trade, investment and technology."],["Business effect","More competition and choice, with pressure to improve quality, productivity and innovation."]]},{title:"Demonetisation in the syllabus",lead:"Treat the case by separating the policy action from its short- and longer-term effects.",items:[["Meaning","Specified currency notes cease to be legal tender, subject to the announced exchange or deposit arrangements."],["Aims discussed in the chapter","Curb unaccounted cash, counterfeit currency and illegal activity; encourage formal and digital transactions."],["Possible effects","Short-term cash disruption alongside greater bank deposits, digital payments and formalisation."],["Case method","State the policy, identify the affected force or stakeholder, then explain the consequence."]]}],compare:{title:"Dimension spotter",heads:["If the case mentions…","Dimension","Example effect"],rows:[["Inflation, interest rate, income","Economic","Changes cost, demand or borrowing"],["Lifestyle, family or values","Social","Changes product preferences"],["Automation or new process","Technological","Changes productivity and skills needed"],["Government priority or stability","Political","Changes confidence or support"],["New rule, act or court order","Legal","Changes what the business may do"]]},cues:[["A rise in interest rates changes borrowing cost","Economic environment"],["Young buyers shift toward subscription access","Social environment"],["Automation changes the skills needed on a production line","Technological environment"],["A new labour law changes hiring requirements","Legal environment"],["Import controls change after a government policy decision","Political environment"]],cards:[["Business environment","The totality of external forces, individuals and institutions that affect business performance."],["Interrelatedness","Different environmental forces are connected; a change in one can affect others."],["Dynamism","The business environment keeps changing over time."],["Complexity","Many forces and their interactions make the environment difficult to understand fully."],["Economic environment","Forces such as income, inflation, interest rates, taxation and economic growth."],["Social environment","Customs, values, lifestyle, demographics, education and consumer preferences."],["Technological environment","Innovation, automation, digital systems and production methods."],["Political environment","Government stability, priorities and attitude toward business."],["Legal environment","Acts, rules, court decisions and administrative orders affecting business."],["Globalisation","Integration of a country's economy with the world economy."]],mcqs:[{q:"A new law changes the labels that food companies must display. Which dimension is most directly involved?",o:["Legal","Social","Economic","Technological"],a:0,x:"Acts and rules are part of the legal environment."},{q:"A rise in disposable income changes demand for premium goods. This is a change in the:",o:["Economic environment","Political environment","Legal environment","Technological environment"],a:0,x:"Income and purchasing power are economic forces."},{q:"A company notices a new customer preference before competitors and launches a suitable product. This shows the environment helps identify:",o:["Opportunities","Authority","Scalar chains","Internal strengths only"],a:0,x:"Environmental scanning helps identify opportunities and first-mover advantages."},{q:"When a change in one external force affects other forces, the feature is:",o:["Interrelatedness","Relativity","Pervasiveness","Standardisation"],a:0,x:"Environmental dimensions are interrelated."},{q:"A business environment is called relative because:",o:["The same condition can affect businesses differently","All businesses face identical effects","It never changes","Only local forces matter"],a:0,x:"Effects vary by place, industry and firm."},{q:"Which is a technological factor?",o:["Use of robotics in assembly","A change in family size","A change in income tax law","A new government coalition"],a:0,x:"Robotics and production methods are technological forces."},{q:"Reducing unnecessary government restrictions on business is:",o:["Liberalisation","Privatisation","Globalisation","Nationalisation"],a:0,x:"Liberalisation reduces controls and restrictions."},{q:"A domestic firm faces more foreign competitors after trade integration. This reflects:",o:["Globalisation","Centralisation","Formalisation","Standardisation"],a:0,x:"Globalisation integrates domestic business with the world economy."},{q:"A sudden policy announcement makes the effect and timing of market changes difficult to predict. Which feature is highlighted?",o:["Uncertainty","Unity of command","Order","Simplification"],a:0,x:"Environmental forces are uncertain because future changes and impacts are difficult to predict."}],subjective:[{m:2,case:"A rise in interest rates increases the monthly loan payments of a retail chain.",q:"Identify the dimension and state one likely business effect. (2 marks)",key:["Economic environment.","Borrowing costs rise, possibly limiting expansion or increasing operating costs."]},{m:2,q:"State any two features of the business environment. (2 marks)",key:["Any two explained: totality; specific and general forces; interrelatedness; dynamism; uncertainty; complexity; relativity."]},{m:2,case:"A new packaging law requires firms to print additional product information.",q:"Identify the environmental dimension and the source of the change. (2 marks)",key:["Legal environment.","A law or regulation changes the conditions under which the business operates."]},{m:2,q:"Distinguish between liberalisation and globalisation. (2 marks)",key:["Liberalisation reduces domestic controls and restrictions.","Globalisation integrates the domestic economy with the world economy."]},{m:2,case:"A firm sees customers shifting from large packages to refill packs.",q:"Which environmental dimension is most directly indicated? Explain. (2 marks)",key:["Social environment.","Consumer lifestyle, values and preferences are changing."]},{m:2,q:"State two ways environmental awareness helps a business. (2 marks)",key:["Any two: identify opportunities; detect threats; access resources; adapt to change; improve performance or image."]},{m:3,q:"Explain any three features of the business environment. (3 marks)",key:["Name and explain any three: dynamic, uncertain, complex, interrelated, relative, totality of external forces."]},{m:3,case:"A company faces a new tax rule, rising borrowing costs and growing preference for low-waste products.",q:"Identify the three environmental dimensions and match each change. (3 marks)",key:["Legal: new tax rule.","Economic: borrowing cost/interest rates.","Social: preference for low-waste products."]},{m:3,q:"Explain how environmental awareness helps a business identify opportunities and threats. (3 marks)",key:["Scanning reveals emerging customer needs, technology or market gaps.","It gives time to act before competitors and gain advantage.","It warns of regulation, substitutes, cost increases or demand shifts so the firm can prepare."]},{m:3,q:"Explain the three elements of the 1991 reform package. (3 marks)",key:["Liberalisation: reduce controls and restrictions.","Privatisation: expand the private sector's role in selected areas.","Globalisation: integrate the economy with world markets."]},{m:3,case:"A sudden digital payment shift creates new sales opportunities but leaves a cash-dependent supplier unable to settle invoices.",q:"Explain two ways the same environmental change can create opportunity and threat. (3 marks)",key:["Digital adoption can create new channels or lower transaction friction.","It can disadvantage firms and suppliers lacking the needed systems or skills.","Business effects are relative and differ by firm capabilities."]},{m:3,q:"Explain three dimensions of the business environment with one example each. (3 marks)",key:["Any three correct dimensions—economic, social, technological, political, legal—with one relevant example each."]},{m:4,q:"Explain four reasons why understanding the business environment is important. (4 marks)",key:["Identifies opportunities and first-mover advantage.","Helps identify threats and prepare.","Helps access resources and adapt plans.","Can improve performance, competitiveness and public image."]},{m:4,case:"A consumer-goods company sees rising income, smaller families, a new recycling rule and low-cost automation becoming available.",q:"Classify the four changes and explain one possible business response to each. (4 marks)",key:["Rising income: economic; adapt price or product mix.","Smaller families: social; adjust pack sizes.","Recycling rule: legal; redesign packaging and comply.","Automation: technological; assess investment and reskill employees."]},{m:4,q:"Explain the features of dynamism, uncertainty, complexity and relativity. (4 marks)",key:["Dynamism: conditions keep changing.","Uncertainty: future changes or effects are difficult to predict.","Complexity: many forces interact.","Relativity: the same change affects firms or locations differently."]},{m:4,case:"After trade barriers are reduced, a domestic manufacturer receives new technology options but faces more foreign competitors.",q:"Identify the reform and explain two opportunities and two challenges for the manufacturer. (4 marks)",key:["Liberalisation/globalisation may be identified with accurate explanation.","Opportunities: access to technology, larger markets, inputs or investment.","Challenges: stronger competition, need to improve quality/productivity, pressure on price.","Responses should adapt plans to the changed environment."]},{m:4,q:"Distinguish between specific and general forces in the business environment. Give examples. (4 marks)",key:["Specific forces affect a particular firm directly: customers, suppliers, competitors, investors.","General forces shape the wider context: economic, social, technological, political or legal conditions.","Give a correct example of each.","Explain that both influence business decisions."]}],
},
{id:"4",title:"Planning",focus:"How an organisation chooses objectives, evaluates options and turns a preferred course into action.",headline:"Planning chooses the path before people and resources are committed.",takeaways:["Planning sets objectives and selects a course of action in advance; it is future-oriented, pervasive and a mental exercise.","The process moves from objectives through premises, alternatives, evaluation and selection to supporting plans and implementation.","Planning reduces uncertainty but cannot guarantee success; it can also create rigidity and delay."],flow:[["Set goals","Decide what to achieve"],["Premises","Forecast assumptions"],["Options","Find possible courses"],["Evaluate","Compare costs and results"],["Choose + act","Select, support, implement"]],sections:[{title:"Meaning and features",lead:"Planning involves setting objectives for a period, considering alternative courses and choosing the best feasible path.",items:[["Primary function","Other functions are organised around the chosen objectives."],["Pervasive","All managers plan, but the scope and time horizon differ by level."],["Continuous and future-focused","Plans are reviewed as conditions change."],["Involves choice","Compare alternatives and select a course."],["Mental exercise","Requires forecasting, analysis and judgement."]]},{title:"Why plan",lead:"Planning gives direction and makes coordinated action possible.",items:[["Provides direction","Everyone understands priorities and targets."],["Reduces overlapping and waste","Activities can be aligned before execution."],["Reduces uncertainty","Managers anticipate change and prepare responses."],["Encourages innovation","Alternatives prompt new ideas."],["Supports control","Standards and targets make comparison possible."]]},{title:"Limits of planning",lead:"Planning helps, but it is not a promise that the future will cooperate.",items:[["Creates rigidity","People may follow an outdated plan despite changed conditions."],["May not work in a dynamic environment","Assumptions can quickly become wrong."],["Can reduce creativity","Detailed instructions may discourage initiative."],["Involves cost and time","Research, forecasting and meetings use resources."],["No guarantee of success","External events and execution quality still matter."]]},{title:"Planning process",lead:"Use the order as a framework for long-answer and case questions.",items:[["1–2","Set objectives; develop planning premises about assumptions and conditions."],["3–4","Identify alternative courses; evaluate their merits, risks and resource needs."],["5–6","Select a course; formulate derivative/supporting plans."],["7","Translate plans into budgets, schedules and procedures; implement and review."]]},{title:"Types of plans",lead:"Standing plans guide recurring situations; single-use plans serve a specific purpose or period.",items:[["Objective","Specific result an organisation seeks."],["Strategy","Broad long-term plan for scope, direction and resource allocation."],["Policy","General guideline that leaves room for judgement."],["Procedure and method","Procedure gives chronological steps; a method specifies how a task is performed."],["Rule","A specific required or prohibited action with little discretion."],["Programme and budget","Programme combines objectives, policies, procedures and resources; budget expresses a plan numerically."]]}],compare:{title:"Plan type in one line",heads:["Plan","What it provides","Case wording"],rows:[["Policy","General decision guideline","Normally, preference is given to existing suppliers"],["Procedure","Sequence of steps","First inspect, then record, then approve"],["Rule","Specific must/must not","No smoking inside the premises"],["Budget","Numerical expected result","₹X allocated; Y units expected"],["Strategy","Broad long-term direction","Enter a new segment over three years"]]},cues:[["A firm states the sales result it wants by year-end","Objective"],["A broad long-term approach allocates resources to expansion","Strategy"],["A manager may use judgement within a general guideline","Policy"],["The case lists ordered steps that must be followed","Procedure"],["A numerical plan helps compare actual spending with expected spending","Budget"]],cards:[["Planning","Setting objectives, considering alternatives and selecting a course of action in advance."],["Planning premise","An assumption or forecast about conditions in which a plan will operate."],["Policy","A general guideline for managerial decisions that permits some judgement."],["Procedure","A chronological sequence of steps for handling recurring work."],["Rule","A specific statement of required or prohibited action, with little discretion."],["Strategy","A broad long-term plan for the organisation's direction and resource allocation."],["Budget","A plan expressed in numerical terms, such as money, time or units."],["Programme","A comprehensive single-use plan combining objectives, policies, procedures and resources."],["Planning process","Objectives, premises, alternatives, evaluation, selection, supporting plans and implementation."],["Limitation of planning","Plans can become rigid or fail when assumptions and external conditions change."]],mcqs:[{q:"A no-smoking instruction allows virtually no discretion. It is a:",o:["Rule","Policy","Strategy","Programme"],a:0,x:"A rule states a specific required or prohibited action."},{q:"A guideline that gives managers room to judge a supplier choice is a:",o:["Policy","Rule","Method","Budget"],a:0,x:"Policies guide decisions but allow judgement."},{q:"Which plan is expressed in numerical terms?",o:["Budget","Strategy","Procedure","Objective"],a:0,x:"Budgets quantify expected results or resource use."},{q:"Which step follows the identification of alternative courses of action?",o:["Evaluate the alternatives","Set objectives","Implement supporting plans","Develop premises"],a:0,x:"Alternatives are evaluated before one is selected."},{q:"A company sets a broad three-year direction to enter a new market. This is a:",o:["Strategy","Rule","Method","Procedure"],a:0,x:"Strategy is a broad, long-term plan."},{q:"Planning is called pervasive because:",o:["Managers at every level do it","Only top managers do it","It ends when a plan is written","It removes all uncertainty"],a:0,x:"All managers plan, with different scope and time horizons."},{q:"A plan may reduce creativity when:",o:["Rigid instructions discourage initiative","Alternatives are evaluated","Employees participate","Assumptions are revised"],a:0,x:"Overly rigid plans may discourage new ideas and initiative."},{q:"The chronological sequence for handling a recurring task is a:",o:["Procedure","Policy","Objective","Strategy"],a:0,x:"Procedures describe steps to be followed in order."},{q:"Which is a realistic limitation of planning?",o:["It cannot guarantee success","It always prevents change","It makes control impossible","It replaces all managerial judgement"],a:0,x:"Plans cannot control every external change or ensure effective execution."}],subjective:[{m:2,case:"A manager provides a general preference for local suppliers but permits exceptions when quality is inadequate.",q:"Identify the type of plan and explain why it fits. (2 marks)",key:["Policy.","It guides decisions while leaving room for managerial judgement."]},{m:2,q:"State any two features of planning. (2 marks)",key:["Any two: primary function; pervasive; continuous; future-oriented; involves choice; mental exercise."]},{m:2,case:"An office instruction lists the steps: receive invoice, verify order, approve payment, record it.",q:"Identify the plan type and state what makes it distinct. (2 marks)",key:["Procedure.","It gives a chronological sequence of steps for recurring work."]},{m:2,q:"State two limitations of planning. (2 marks)",key:["Any two: rigidity; assumptions may fail; cost/time; may reduce creativity; no guarantee of success."]},{m:2,case:"A warehouse displays a sign prohibiting smoking anywhere inside.",q:"Identify the type of plan and explain the discretion allowed. (2 marks)",key:["Rule.","It prescribes or prohibits a specific action and allows little or no discretion."]},{m:2,q:"Why does planning facilitate control? (2 marks)",key:["Planning sets objectives and standards.","Actual performance can then be compared with those planned standards."]},{m:3,q:"Explain any three steps in the planning process. (3 marks)",key:["Any three in correct sequence and explanation: objectives; premises; alternatives; evaluation; selection; derivative plans; implementation/follow-up."]},{m:3,case:"A company forecasts demand, lists three expansion options and compares their costs before choosing one.",q:"Identify three planning steps illustrated. (3 marks)",key:["Developing planning premises through the demand forecast.","Identifying alternative courses of action.","Evaluating alternatives by comparing costs before selection."]},{m:3,q:"Explain three benefits of planning. (3 marks)",key:["Provides direction.","Reduces overlapping and waste or uncertainty.","Encourages innovation, improves decisions or establishes standards for control (one explained)."]},{m:3,q:"Distinguish between a policy, a procedure and a rule. (3 marks)",key:["Policy: general guideline with judgement.","Procedure: ordered steps for recurring work.","Rule: specific instruction with little discretion."]},{m:3,case:"A manager refuses to revise a launch plan even after a new regulation invalidates its assumptions.",q:"Identify two limitations of planning shown and explain. (3 marks)",key:["Rigidity: people persist with the original course.","Plans may fail in a dynamic environment because premises have changed.","Planning cannot guarantee success if conditions change or implementation is poor."]},{m:3,q:"Explain why planning is both pervasive and continuous. (3 marks)",key:["All managers plan, though scope and horizon differ.","Plans need review as conditions change.","New plans follow from results and changing objectives."]},{m:4,q:"Explain the planning process in a logical sequence. (4 marks)",key:["Set objectives and develop premises.","Identify and evaluate alternative courses.","Select the best feasible course and develop supporting plans.","Translate into budgets/schedules, implement and review."]},{m:4,case:"A firm wants to open a second factory. It forecasts demand, compares locations, chooses one and assigns a budget and schedule.",q:"Match four actions in the case to planning steps. (4 marks)",key:["Forecast demand: develop planning premises.","Compare locations: identify/evaluate alternatives.","Choose one: select a course of action.","Assign budget and schedule: derivative plans and implementation."]},{m:4,q:"Explain four limitations of planning. (4 marks)",key:["Creates rigidity.","May fail when the environment changes quickly.","Can reduce creativity or initiative.","Consumes time/resources and does not guarantee success (explain any four)."]},{m:4,case:"A retailer writes no-smoking rules, a supplier-selection guideline, a delivery sequence and a monthly spending cap.",q:"Identify the four types of plan shown. (4 marks)",key:["No-smoking instruction: rule.","Supplier-selection guideline: policy.","Delivery sequence: procedure.","Monthly spending cap: budget."]},{m:4,q:"Explain the importance of planning and its relationship with controlling. (4 marks)",key:["Planning provides direction, reduces overlapping/waste and anticipates uncertainty.","It encourages innovation and supports better decisions.","Planning sets the objectives and standards.","Control compares actual results with those standards and feeds corrections into future plans."]}],
},
{id:"5",title:"Organising",focus:"How work is divided, grouped and connected through authority and responsibility.",headline:"Organising turns a plan into jobs, teams and reporting lines.",takeaways:["Organising identifies and divides work, groups related activities, assigns duties and establishes reporting relationships.","Structure can be functional (by function) or divisional (by product, territory or customer).","Delegation transfers authority to act but the manager retains ultimate accountability; decentralisation spreads decision-making more broadly."],flow:[["Identify","List required work"],["Group","Create departments"],["Assign","Allocate duties"],["Authority","Link reporting lines"],["Review","Adapt the structure"]],sections:[{title:"Organising process",lead:"The process converts objectives into a workable structure.",items:[["1. Identify and divide work","Break the total work into manageable activities."],["2. Departmentalise","Group similar or related activities."],["3. Assign duties","Match jobs to people and roles."],["4. Establish reporting relationships","Define authority, responsibility and accountability."]]},{title:"Organisation structures",lead:"Choose the structure that best supports the product range and coordination needs.",items:[["Functional","Groups jobs by functions such as production, marketing, finance and HR."],["Divisional","Groups work around products, territories or customers; each division may have its own functions."],["Functional strength","Specialisation and economies of scale."],["Divisional strength","Clear product accountability and faster cross-functional response."],["Trade-off","Functional silos can slow product decisions; divisional duplication can raise cost."]]},{title:"Formal and informal organisation",lead:"Formal structure is designed; informal relationships emerge through social interaction.",items:[["Formal organisation","Official roles, rules, authority and channels created deliberately."],["Informal organisation","Unofficial social network that can spread information quickly and support belonging."],["Risks of informal networks","Rumours or resistance can spread; they do not replace formal accountability."],["Manager's task","Use informal communication constructively while clarifying official decisions."]]},{title:"Delegation",lead:"Delegation frees managers to focus while developing subordinates.",items:[["Authority","Right to make decisions and use resources within limits; flows downward."],["Responsibility","Obligation to perform the assigned duty; cannot simply be passed on."],["Accountability","Answerability for results; remains with the manager who delegated."],["Importance","Enables specialisation, faster decisions, growth, subordinate development and motivation."]]},{title:"Decentralisation",lead:"Decentralisation is a systematic, organisation-wide distribution of decision authority to lower levels.",items:[["Meaning","Significant decision authority is distributed across levels and units."],["Benefits","Quicker local decisions, initiative, development of managers, growth and better control through unit accountability."],["Not the same as delegation","Delegation is a manager-subordinate relationship; decentralisation is a broader organisational policy."],["Balance","Top management retains essential strategic decisions while local units act within boundaries."]]}],compare:{title:"Delegation and decentralisation",heads:["Dimension","Delegation","Decentralisation"],rows:[["Scope","A manager assigns authority and duty to a subordinate","Organisation-wide distribution of authority"],["Nature","Necessary in all organisations","A deliberate policy choice and degree"],["Focus","Manager-subordinate relationship","Where decisions are made across the organisation"],["Accountability","Manager remains ultimately accountable","Top management retains overall responsibility"]]},cues:[["Departments are grouped around finance, marketing and production","Functional structure"],["Each product line has its own manager and functions","Divisional structure"],["A supervisor gives a subordinate authority for a defined task","Delegation"],["Local branches can make defined decisions without waiting for head office","Decentralisation"],["Employees exchange information over unofficial social relationships","Informal organisation"]],cards:[["Organising","Identifying and dividing work, grouping activities, assigning duties and establishing authority relationships."],["Functional structure","An organisation structure that groups jobs by functions such as production, marketing and finance."],["Divisional structure","An organisation structure that groups work around products, territories or customers."],["Formal organisation","Officially designed roles, authority, rules and reporting relationships."],["Informal organisation","Unofficial relationships that develop through social interaction among employees."],["Delegation","A manager assigns duties and grants authority to a subordinate while retaining accountability."],["Authority","The right to make decisions, issue instructions and use resources within limits."],["Responsibility","The obligation to perform an assigned duty."],["Accountability","Answerability for the final outcome; it cannot be delegated away."],["Decentralisation","Systematic distribution of decision-making authority to lower levels across the organisation."]],mcqs:[{q:"An organisation groups marketing, finance and production jobs into separate departments. This is:",o:["Functional structure","Divisional structure","Informal organisation","Decentralisation"],a:0,x:"Functional structure groups work by business function."},{q:"Each product line has its own production, marketing and finance teams. This is:",o:["Divisional structure","Functional structure","Scalar chain","Informal organisation"],a:0,x:"A divisional structure groups work around products, territories or customers."},{q:"Which element of delegation remains with the manager who assigned the task?",o:["Accountability","Authority","Duty","Operational freedom"],a:0,x:"The manager remains answerable for the final outcome."},{q:"The right to make decisions within assigned limits is:",o:["Authority","Responsibility","Accountability","Initiative"],a:0,x:"Authority is the right to act, decide and use resources within limits."},{q:"Unofficial friendships become a fast channel for workplace information. This is:",o:["Informal organisation","Formal organisation","Departmentalisation","Delegation"],a:0,x:"Informal organisation develops through social interaction."},{q:"Organisation-wide distribution of decision authority to lower levels is:",o:["Decentralisation","Delegation","Departmentalisation","Centralisation"],a:0,x:"Decentralisation is a broad organisational policy of dispersing authority."},{q:"Which is a likely advantage of functional structure?",o:["Specialisation within functions","No need for coordination","No duplication under any condition","Every product is independently accountable"],a:0,x:"Functional departments develop specialised knowledge and economies of scale."},{q:"Which delegation statement is correct?",o:["Authority may be granted, but ultimate accountability remains with the manager","Responsibility disappears after delegation","Accountability flows to the lowest level only","Authority and responsibility are unrelated"],a:0,x:"Delegation grants authority and assigns responsibility, but the manager remains accountable."},{q:"A local branch can resolve routine customer issues within a set limit. This illustrates:",o:["Decentralisation","Unity of direction","Formalisation only","Motion study"],a:0,x:"Decision authority has been distributed to a lower level."}],subjective:[{m:2,case:"A manager assigns a stock audit to an assistant and authorises access to inventory records.",q:"Identify two elements of delegation shown. (2 marks)",key:["Responsibility: the assistant must perform the stock audit.","Authority: access and decision rights are granted to complete it."]},{m:2,q:"Name the four steps in the organising process. (2 marks)",key:["Identify and divide work; departmentalise; assign duties; establish reporting relationships."]},{m:2,q:"Distinguish between authority and responsibility. (2 marks)",key:["Authority is the right to act or decide within limits.","Responsibility is the obligation to perform the assigned duty."]},{m:2,case:"Employees share unofficial advice through friendships across departments.",q:"Identify the type of organisation and one benefit. (2 marks)",key:["Informal organisation.","It can spread information quickly, support belonging or help cooperation."]},{m:2,q:"State one difference between functional and divisional structure. (2 marks)",key:["Functional groups jobs by function; divisional groups work around a product, territory or customer."]},{m:2,q:"What is decentralisation? (2 marks)",key:["It is systematic distribution of decision-making authority to lower levels across the organisation."]},{m:3,q:"Explain the organising process. (3 marks)",key:["Identify and divide work.","Group related activities into departments and assign duties.","Establish authority and reporting relationships."]},{m:3,case:"A consumer-goods company organises by product, with each line responsible for its own sales, production and finance.",q:"Identify the structure and state two advantages. (3 marks)",key:["Divisional structure.","Clear product accountability and easier performance measurement.","Faster cross-functional decisions or flexibility as products grow (one)."]},{m:3,q:"Explain the three elements of delegation. (3 marks)",key:["Authority: right to decide and act within limits.","Responsibility: obligation to complete assigned work.","Accountability: answerability for results; retained by the delegating manager."]},{m:3,case:"A head-office manager approves every small local service recovery, creating long queues for routine decisions.",q:"Suggest how decentralisation could help and name one safeguard. (3 marks)",key:["Distribute defined decision authority to local managers.","Routine issues can be resolved faster near the customer.","Set limits, standards and reporting so local authority stays aligned."]},{m:3,q:"Explain three advantages of delegation. (3 marks)",key:["Reduces manager workload and enables focus on priorities.","Speeds decisions and improves response.","Develops subordinate skills, motivation or growth capacity (one explained)."]},{m:3,q:"Distinguish formal and informal organisation. (3 marks)",key:["Formal is deliberately designed, with official roles and reporting lines.","Informal emerges through social interaction.","Formal creates accountability; informal can communicate quickly but can also spread rumours."]},{m:4,q:"Compare functional and divisional structures on basis, strengths and limitations. (4 marks)",key:["Functional: grouped by business function; supports specialisation and scale.","Functional limitation: departmental silos can slow coordination.","Divisional: grouped by products/territories/customers; supports clear accountability and flexibility.","Divisional limitation: may duplicate functions and raise cost."]},{m:4,case:"A manager gives an employee a target and resources, but later says the employee alone is responsible for all consequences.",q:"Assess the statement using delegation elements. (4 marks)",key:["Target and duty create responsibility.","Resources or decision rights represent authority.","Accountability for final outcome remains with the manager who delegated.","Clarify limits and maintain follow-up; delegation does not remove the manager's answerability."]},{m:4,q:"Explain four benefits of decentralisation. (4 marks)",key:["Quicker decisions close to the situation.","Develops initiative and managerial talent.","Supports expansion and local responsiveness.","Improves control through clearer unit accountability or reduces burden on top managers."]},{m:4,case:"A firm grows from one product to six; functional departments struggle to coordinate launches and cost is rising.",q:"Recommend a structure and discuss one benefit and one risk. (4 marks)",key:["A divisional structure by product may improve product accountability and coordination.","Each product team can align production, marketing and finance around its goals.","It may improve speed and customer focus.","Possible risk: duplicated resources and higher cost; coordinate shared services where suitable."]},{m:4,q:"Explain how delegation supports effective management while preserving accountability. (4 marks)",key:["Assign duties and define expected results.","Grant sufficient authority to perform the task.","Subordinates gain skills and managers can focus on higher priorities.","Managers retain accountability and monitor results."]}],
},
{id:"6",title:"Staffing",focus:"How organisations forecast people needs, recruit and select people, then help them grow.",headline:"Right people, right roles, right skills—then keep developing them.",takeaways:["Staffing obtains, deploys and maintains a capable workforce; it is continuous and important at every level.","Recruitment creates a pool of applicants; selection screens that pool to choose the best fit.","Training improves job skills for current work; development prepares people for wider future responsibilities."],flow:[["Plan people","Estimate needs"],["Recruit","Attract applicants"],["Select","Assess and choose"],["Place + orient","Assign and introduce"],["Train","Build performance"]],sections:[{title:"Staffing and workforce planning",lead:"Staffing ensures the organisation has the right number and kind of people when and where needed.",items:[["Estimate manpower needs","Forecast quantity and qualifications by role and time."],["Recruitment","Search for and attract prospective applicants."],["Selection","Assess applicants and choose the most suitable."],["Placement and induction","Assign a role and help a new employee understand the organisation."],["Training and development","Improve present performance and future capacity."]]},{title:"Recruitment sources",lead:"Internal sources use current employees; external sources reach beyond the organisation.",items:[["Internal: promotion or transfer","Faster and motivating; employees and performance are known."],["Internal trade-off","May limit fresh ideas and leave another vacancy."],["External: advertising, agencies, campus, employment exchange, online","Wider choice and new skills."],["External trade-off","Can cost more, take longer and affect existing employees' morale."]]},{title:"Selection sequence",lead:"Selection is a screening process; steps may vary but follow a logical order.",items:[["1–3","Preliminary screening; application form; selection tests."],["4–6","Employment interview; reference/background checks; medical examination."],["7–8","Job offer; contract and placement; induction."],["Test examples","Aptitude assesses capacity to learn; trade tests assess job skill; personality tests assess traits; interest tests assess preferences."]]},{title:"Training and development",lead:"Training focuses more directly on current job skills; development has a broader, long-term focus.",items:[["Benefits to the organisation","Higher productivity and quality, fewer accidents, less supervision, better morale and lower turnover."],["Benefits to the employee","Improved skill, confidence, earnings, safety and career opportunities."],["On-the-job methods","Apprenticeship, coaching, job rotation, internship; learn while doing real work."],["Off-the-job methods","Vestibule training, lectures, case studies, conferences, films; learn away from the actual job."]]},{title:"Induction and placement",lead:"Recruiting the right person is not the end of staffing.",items:[["Placement","Assign the selected person to a role suited to their qualifications."],["Induction","Introduce the organisation, colleagues, rules, facilities and job expectations."],["Follow-up","Training and feedback help a new employee settle and perform."]]}],compare:{title:"Recruitment and selection",heads:["Dimension","Recruitment","Selection"],rows:[["Purpose","Attract a pool of applicants","Choose the most suitable applicant"],["Nature","Positive: encourages applications","Screening: may reject applicants"],["Order","Comes first","Follows recruitment"],["Result","Applicants available","Candidate placed in a job"]]},cues:[["Company attracts candidates through a campus fair","External recruitment"],["An employee moves to a higher role","Promotion: internal recruitment"],["Applicants complete a reasoning assessment","Selection test"],["New employee learns by shadowing an experienced technician","On-the-job training / coaching"],["Employees train on simulated equipment away from production","Vestibule training"]],cards:[["Staffing","Obtaining, deploying and maintaining a suitable workforce."],["Recruitment","Searching for and attracting prospective employees to apply for jobs."],["Selection","Screening applicants to choose the most suitable candidate."],["Internal recruitment","Filling a vacancy from within the organisation, such as through promotion or transfer."],["Induction","Introducing a new employee to the organisation, colleagues, rules and job."],["Aptitude test","A selection test that measures a person's potential to learn a skill."],["Trade test","A test that measures proficiency or skill in a specific job."],["On-the-job training","Learning while performing the actual job, often through coaching or apprenticeship."],["Vestibule training","Off-the-job training using equipment that simulates the actual workplace."],["Development","A broader, longer-term process that prepares employees for future responsibilities."]],mcqs:[{q:"Which statement best distinguishes recruitment from selection?",o:["Recruitment attracts applicants; selection chooses among them","Recruitment rejects applicants; selection advertises jobs","They are the same process","Selection happens before a vacancy exists"],a:0,x:"Recruitment creates an applicant pool; selection screens it."},{q:"A test measures a candidate's potential to learn a skill. It is an:",o:["Aptitude test","Trade test","Interest test","Personality test"],a:0,x:"Aptitude tests measure potential to learn."},{q:"A candidate demonstrates how to use a specific machine. This is a:",o:["Trade test","Aptitude test","Interest test","Personality test"],a:0,x:"Trade tests assess proficiency in a particular skill."},{q:"Learning by working alongside an experienced craftsperson is:",o:["Apprenticeship training","Vestibule training","Lecture","Case study"],a:0,x:"Apprenticeship is an on-the-job training method."},{q:"Training on simulated equipment in a separate area is:",o:["Vestibule training","Job rotation","Internship","Coaching"],a:0,x:"Vestibule training simulates the work environment away from the actual job."},{q:"Which is a likely advantage of internal recruitment?",o:["Employees' abilities are already known","It always introduces new ideas","It creates a larger outside applicant pool","It never creates a vacancy"],a:0,x:"The organisation has information about internal candidates and it may motivate staff."},{q:"The process of introducing a new hire to rules, colleagues and facilities is:",o:["Induction","Recruitment","Selection","Development"],a:0,x:"Induction helps a new employee understand the organisation and role."},{q:"Training mainly differs from development because training is more:",o:["Focused on current job skills","Focused only on retirement","Unrelated to performance","Broad and long-term in every case"],a:0,x:"Training tends to focus on present job requirements; development is broader and future-oriented."},{q:"Which is an off-the-job training method?",o:["Case study in a training room","Job rotation","Coaching","Apprenticeship"],a:0,x:"A case study can be used away from the actual worksite."}],subjective:[{m:2,case:"An employer searches for applicants and invites them to submit applications.",q:"Name the staffing activity and state its purpose. (2 marks)",key:["Recruitment.","It attracts a pool of prospective candidates for the vacancy."]},{m:2,q:"Distinguish between training and development. (2 marks)",key:["Training focuses mainly on current job skills and performance.","Development has a broader, longer-term focus on future responsibilities."]},{m:2,case:"A candidate sits a test that checks ability to learn a new technical skill.",q:"Identify the test and explain what it measures. (2 marks)",key:["Aptitude test.","It measures the potential to acquire a skill."]},{m:2,q:"State two benefits of training to employees. (2 marks)",key:["Any two: improved skills, confidence, safety, earnings, job satisfaction or career opportunities."]},{m:2,case:"An employee is moved to a higher position to fill a vacancy.",q:"Identify the recruitment source and give one possible benefit. (2 marks)",key:["Internal recruitment through promotion.","It can motivate staff, cost less or use known performance information."]},{m:2,q:"What is induction? (2 marks)",key:["Introducing a new employee to the organisation, colleagues, facilities, rules and job expectations."]},{m:3,q:"Explain three steps in the selection process. (3 marks)",key:["Any three correctly sequenced: preliminary screening/application; tests; interview; references; medical exam; job offer/placement; induction."]},{m:3,case:"A hotel hires seasonal staff but receives complaints about inconsistent service and repeated mistakes.",q:"Recommend three staffing or training actions. (3 marks)",key:["Forecast required number and skills before the season.","Use suitable recruitment and selection to match roles.","Provide job training and induction; explain standards and check performance."]},{m:3,q:"Explain three advantages of external recruitment. (3 marks)",key:["Provides a wider applicant pool.","Can bring new skills, ideas and experience.","May help meet growth or specialised needs quickly (explain a valid advantage)."]},{m:3,q:"Explain three benefits of training to an organisation. (3 marks)",key:["Raises productivity and quality.","Reduces accidents, supervision needs or operating waste.","Can improve morale and lower absenteeism or turnover."]},{m:3,case:"A candidate is interviewed, reference-checked and medically examined after passing an aptitude test.",q:"Explain the purpose of any three selection steps shown. (3 marks)",key:["Aptitude test: assesses potential to learn.","Interview: assesses suitability and lets both sides clarify the role.","References check background; medical exam verifies fitness for the job (any three steps accurately explained)."]},{m:3,q:"Distinguish between on-the-job and off-the-job training, with examples. (3 marks)",key:["On-the-job: learn while doing actual work; e.g. coaching/apprenticeship.","Off-the-job: learn away from the actual job; e.g. vestibule, lecture or case study.","Match examples and explain the work setting."]},{m:4,q:"Describe four stages in the staffing process. (4 marks)",key:["Estimate manpower requirements.","Recruit candidates and select the best fit.","Place and induct the selected employee.","Train/develop employees and review performance."]},{m:4,case:"A factory needs ten machine operators. It advertises externally, uses trade tests and trains selected applicants on equipment in a separate simulation room.",q:"Identify the recruitment source, selection method and training method; explain each. (4 marks)",key:["External recruitment: attracts candidates from outside.","Trade test: checks skill in operating relevant equipment.","Vestibule training: uses simulated equipment away from the actual work area.","Explain how each stage reduces skill mismatch before live production."]},{m:4,q:"Explain the selection process in a logical sequence. (4 marks)",key:["Preliminary screening and application information.","Selection tests followed by interview.","Reference/background checks and medical examination.","Job offer, placement and induction."]},{m:4,case:"A firm fills every vacancy by promotion. Experienced staff are pleased, but the business lacks a needed new digital skill and another role remains vacant.",q:"Assess internal recruitment and recommend a balanced approach. (4 marks)",key:["Internal recruitment can motivate and use known employee performance.","It can limit new ideas/skills and create a vacancy elsewhere.","Use internal candidates where skills fit; recruit externally for scarce digital expertise.","Plan transfers, training and succession to address the resulting vacancy."]},{m:4,q:"Explain four benefits of training and development, covering both organisation and employee. (4 marks)",key:["Organisation: higher productivity and quality.","Organisation: fewer accidents, less supervision or lower turnover.","Employee: improved skills, confidence and performance.","Employee: higher earnings, safety, morale or career prospects."]}],
}
]);
